CREATE TABLE "Lobby" ("id" uuid PRIMARY KEY,"kind" text NOT NULL CHECK("kind" IN ('PUBLIC','PRIVATE')),"mode" text NOT NULL DEFAULT 'CLASSIC' CHECK("mode"='CLASSIC'),"capacity" integer NOT NULL CHECK("capacity" BETWEEN 2 AND 6),"hostId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"inviteHash" text UNIQUE,"version" integer NOT NULL DEFAULT 1 CHECK("version">0),"status" text NOT NULL DEFAULT 'OPEN' CHECK("status" IN ('OPEN','CLOSED')),"createdAt" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(("kind"='PRIVATE' AND "inviteHash" ~ '^[a-f0-9]{64}$') OR ("kind"='PUBLIC' AND "inviteHash" IS NULL)));
CREATE TABLE "LobbySeat" ("userId" uuid PRIMARY KEY REFERENCES "User"("id") ON DELETE RESTRICT,"lobbyId" uuid NOT NULL REFERENCES "Lobby"("id") ON DELETE RESTRICT,"seat" integer NOT NULL CHECK("seat" BETWEEN 0 AND 5),"ready" boolean NOT NULL DEFAULT false,CONSTRAINT "LobbySeat_lobbyId_seat_key" UNIQUE("lobbyId","seat"));
CREATE FUNCTION lobby_capacity() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE c integer; s text; BEGIN SELECT "capacity","status" INTO c,s FROM "Lobby" WHERE "id"=NEW."lobbyId" FOR UPDATE; IF s<>'OPEN' OR NEW."seat">=c THEN RAISE EXCEPTION 'invalid lobby seat'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lobby_capacity BEFORE INSERT OR UPDATE ON "LobbySeat" FOR EACH ROW EXECUTE FUNCTION lobby_capacity();

CREATE INDEX "Lobby_kind_mode_status_createdAt_idx" ON "Lobby"("kind","mode","status","createdAt");
